//! Golden tests for the nft program: [`render`] output against the files in `tests/golden/`, byte for byte.
//!
//! The golden files are written by hand from the program text of the contract, never generated by `render`.
//! `program-6.6.nft` is that text itself; the others change only the inputs.

use std::collections::BTreeSet;
use std::error::Error;
use std::net::{Ipv4Addr, Ipv6Addr};

use tn_p2p_allow_sync::addr::{Cidr, parse_cidr_or_host};
use tn_p2p_allow_sync::render::{HEADER, Program, render};

type TestResult = Result<(), Box<dyn Error>>;

/// One golden case: the inputs as text, deliberately out of order and in non-canonical spellings, and the expected program.
struct Case {
    name: &'static str,
    golden: &'static str,
    ports: &'static [u16],
    allow_v4: &'static [&'static str],
    allow_v6: &'static [&'static str],
    static_v4: &'static [&'static str],
    static_v6: &'static [&'static str],
}

/// The 6.6 ports with every set empty; the cases below override what they need.
const BASE: Case = Case {
    name: "",
    golden: "",
    ports: &[49594, 49590],
    allow_v4: &[],
    allow_v6: &[],
    static_v4: &[],
    static_v6: &[],
};

/// The program text of the contract: two allow_v4 elements and one static_v4 network.
const PROGRAM_6_6: Case = Case {
    name: "program-6.6",
    golden: include_str!("golden/program-6.6.nft"),
    allow_v4: &["198.51.100.7", "192.0.2.10"],
    static_v4: &["203.0.113.0/24"],
    ..BASE
};

/// IPv6 only: numeric order differs from text order, and the first of two equal zero runs is the one compressed.
const IPV6_ONLY: Case = Case {
    name: "ipv6-only",
    golden: include_str!("golden/ipv6-only.nft"),
    allow_v6: &[
        "2001:0DB8:0000:0000:0001:0000:0000:0007",
        "2001:db8:0:0:0:0:0:9",
    ],
    static_v6: &["2001:db8:100:0:0:0:0:0/48"],
    ..BASE
};

/// Exactly one element in every set, so every block is inline.
const SINGLE_ELEMENT: Case = Case {
    name: "single-element",
    golden: include_str!("golden/single-element.nft"),
    allow_v4: &["192.0.2.10"],
    allow_v6: &["2001:db8::7"],
    static_v4: &["203.0.113.0/24"],
    static_v6: &["2001:db8:100::/48"],
    ..BASE
};

/// Several static networks per family, given unmasked and out of numeric order, with no allow elements.
const SEVERAL_STATIC: Case = Case {
    name: "several-static",
    golden: include_str!("golden/several-static.nft"),
    static_v4: &[
        "203.0.113.77/24",
        "10.20.0.0/16",
        "192.0.2.0/25",
        "10.3.255.1/16",
    ],
    static_v6: &["fd00:1234:5678::/32", "2001:db8:10::/48", "2001:db8:9::/48"],
    ..BASE
};

/// The 6.6 sets with one port, which keeps its braces.
const SINGLE_PORT: Case = Case {
    name: "single-port",
    golden: include_str!("golden/single-port.nft"),
    ports: &[49590],
    ..PROGRAM_6_6
};

/// Every set empty: no `add element` block at all.
const EMPTY_SETS: Case = Case {
    name: "empty-sets",
    golden: include_str!("golden/empty-sets.nft"),
    ..BASE
};

/// Every case, for the tests that run over all of them.
const CASES: [&Case; 6] = [
    &PROGRAM_6_6,
    &IPV6_ONLY,
    &SINGLE_ELEMENT,
    &SEVERAL_STATIC,
    &SINGLE_PORT,
    &EMPTY_SETS,
];

/// Owned inputs of one program.
struct Sets {
    ports: BTreeSet<u16>,
    allow_v4: BTreeSet<Ipv4Addr>,
    allow_v6: BTreeSet<Ipv6Addr>,
    static_v4: BTreeSet<Cidr>,
    static_v6: BTreeSet<Cidr>,
}

impl Sets {
    fn program(&self) -> Program<'_> {
        Program {
            ports: &self.ports,
            allow_v4: &self.allow_v4,
            allow_v6: &self.allow_v6,
            static_v4: &self.static_v4,
            static_v6: &self.static_v6,
        }
    }
}

/// The items of `items`, reversed when `reverse` is set.
fn ordered<T: Copy>(items: &[T], reverse: bool) -> Vec<T> {
    let mut v = items.to_vec();
    if reverse {
        v.reverse();
    }
    v
}

/// Parses static entries, refusing one of the wrong family so a mistyped case cannot pass by accident.
fn cidrs(items: &[&str], reverse: bool, v4: bool) -> Result<BTreeSet<Cidr>, Box<dyn Error>> {
    let mut set = BTreeSet::new();
    for s in ordered(items, reverse) {
        let cidr = parse_cidr_or_host(s)?;
        if cidr.net.is_ipv4() != v4 {
            return Err(format!("{s} is in the wrong static set").into());
        }
        set.insert(cidr);
    }
    Ok(set)
}

impl Case {
    /// Builds the sets by inserting the items in the order given, or in reverse.
    fn sets(&self, reverse: bool) -> Result<Sets, Box<dyn Error>> {
        Ok(Sets {
            ports: ordered(self.ports, reverse).into_iter().collect(),
            allow_v4: ordered(self.allow_v4, reverse)
                .into_iter()
                .map(str::parse)
                .collect::<Result<_, _>>()?,
            allow_v6: ordered(self.allow_v6, reverse)
                .into_iter()
                .map(str::parse)
                .collect::<Result<_, _>>()?,
            static_v4: cidrs(self.static_v4, reverse, true)?,
            static_v6: cidrs(self.static_v6, reverse, false)?,
        })
    }

    fn render(&self, reverse: bool) -> Result<String, Box<dyn Error>> {
        Ok(render(&self.sets(reverse)?.program()))
    }

    fn assert_golden(&self) -> TestResult {
        assert_eq!(self.render(false)?, self.golden, "golden {}", self.name);
        Ok(())
    }
}

#[test]
fn program_6_6_matches_the_contract_text() -> TestResult {
    PROGRAM_6_6.assert_golden()
}

#[test]
fn ipv6_only() -> TestResult {
    IPV6_ONLY.assert_golden()
}

#[test]
fn single_element_in_every_set_is_inline() -> TestResult {
    SINGLE_ELEMENT.assert_golden()
}

#[test]
fn several_static_entries_sort_by_network() -> TestResult {
    SEVERAL_STATIC.assert_golden()
}

#[test]
fn single_port_keeps_its_braces() -> TestResult {
    SINGLE_PORT.assert_golden()
}

#[test]
fn empty_sets_write_no_element_block() -> TestResult {
    EMPTY_SETS.assert_golden()
}

#[test]
fn permuted_inputs_render_byte_equal() -> TestResult {
    for case in CASES {
        assert_eq!(
            case.render(true)?,
            case.render(false)?,
            "case {}",
            case.name
        );
    }
    Ok(())
}

#[test]
fn every_golden_starts_with_the_header_and_ends_with_one_newline() {
    for case in CASES {
        assert_eq!(case.golden.lines().next(), Some(HEADER), "{}", case.name);
        assert!(case.golden.ends_with("}\n"), "{}", case.name);
        assert!(!case.golden.ends_with("\n\n"), "{}", case.name);
    }
}
